namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public string Department { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

namespace CourseCatalog.Services;

using CourseCatalog.Models;

public interface ICatalogService
{
    List<Course> GetAllCourses();
    List<Course> SearchCourses(string? searchTerm, string? department);
    List<string> GetDepartments();
    Course? GetCourseById(int id);
    List<Course> GetFeaturedCourses();
    void SubmitEnrollment(EnrollmentRequest request);
}

namespace CourseCatalog.Services;

using CourseCatalog.Models;

public class CatalogService : ICatalogService
{
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _courses = new List<Course>
        {
            new Course
            {
                Id = 1, CourseCode = "CS101", Title = "Introduction to Computer Science",
                Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of modern computing topics.",
                Credits = 3, Schedule = "MWF 10:00–10:50 AM", Department = "Computer Science",
                InstructorName = "Dr. Alice Chen",
                InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of experience teaching introductory CS courses.",
                IsFeatured = true
            },
            new Course
            {
                Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Analysis of sorting and searching algorithms with Big-O notation.",
                Credits = 4, Schedule = "TTh 1:00–2:20 PM", Department = "Computer Science",
                InstructorName = "Dr. Brian Park",
                InstructorBio = "Dr. Park specializes in algorithm design and competitive programming. He has published over 30 papers on combinatorial optimization.",
                IsFeatured = true
            },
            new Course
            {
                Id = 3, CourseCode = "CS310", Title = "Database Systems",
                Description = "Principles of database design, relational algebra, SQL, normalization, indexing, and transaction management. Includes a semester-long project building a full-stack application.",
                Credits = 3, Schedule = "MWF 2:00–2:50 PM", Department = "Computer Science",
                InstructorName = "Dr. Alice Chen",
                InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of experience teaching introductory CS courses.",
                IsFeatured = false
            },
            new Course
            {
                Id = 4, CourseCode = "MATH101", Title = "Calculus I",
                Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
                Credits = 4, Schedule = "MWF 9:00–9:50 AM", Department = "Mathematics",
                InstructorName = "Dr. Sarah Kim",
                InstructorBio = "Dr. Kim is an award-winning mathematics educator with a focus on making calculus accessible to all students.",
                IsFeatured = true
            },
            new Course
            {
                Id = 5, CourseCode = "MATH210", Title = "Linear Algebra",
                Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Applications to computer graphics and machine learning.",
                Credits = 3, Schedule = "TTh 10:30–11:50 AM", Department = "Mathematics",
                InstructorName = "Dr. James Liu",
                InstructorBio = "Dr. Liu researches numerical linear algebra and has contributed to several open-source mathematical software libraries.",
                IsFeatured = false
            },
            new Course
            {
                Id = 6, CourseCode = "MATH305", Title = "Probability and Statistics",
                Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world data sets.",
                Credits = 3, Schedule = "MWF 11:00–11:50 AM", Department = "Mathematics",
